import{_ as l,o,c as i,a2 as a}from"./chunks/framework.QCr1ZR1X.js";const g=JSON.parse('{"title":"第4章 边缘计算（教师用书）","description":"","frontmatter":{},"headers":[],"relativePath":"teacher/ch4/教师用书-第4章-边缘计算.md","filePath":"teacher/ch4/教师用书-第4章-边缘计算.md","lastUpdated":1786967935000}'),r={name:"teacher/ch4/教师用书-第4章-边缘计算.md"};function e(d,t,n,u,s,h){return o(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="第4章-边缘计算-教师用书" tabindex="-1">第4章 边缘计算（教师用书） <a class="header-anchor" href="#第4章-边缘计算-教师用书" aria-label="Permalink to &quot;第4章 边缘计算（教师用书）&quot;">​</a></h1><blockquote><p><strong>本章定位</strong>：从&quot;网络互通&quot;向上走到&quot;数据处理&quot;。第3章解决了设备之间如何连接、用什么协议通信的问题，本章回答&quot;数据采集之后怎么办&quot;——如果所有数据都往云端传，带宽不够、延迟太高、成本扛不住。边缘计算就是在数据产生的现场做第一轮处理。 <strong>课时安排</strong>：8课时（理论4 + 实践4），共4次课 <strong>学情分析</strong>：学生已经掌握了Node-RED基础和ModbusTCP通信，但对边缘计算的概念比较陌生；对动手操作兴趣高，对软PLC这样的跨界概念需要直观理解为主，不要求深入编程。本章新增了&quot;边缘-云端正反馈循环&quot;和&quot;ISA-95/IIRA映射&quot;两个概念，需要通过类比和图示帮助学生建立理解。</p></blockquote><hr><h2 id="一、本章教学目标" tabindex="-1">一、本章教学目标 <a class="header-anchor" href="#一、本章教学目标" aria-label="Permalink to &quot;一、本章教学目标&quot;">​</a></h2><h3 id="知识目标" tabindex="-1">知识目标 <a class="header-anchor" href="#知识目标" aria-label="Permalink to &quot;知识目标&quot;">​</a></h3><ol><li>理解边缘计算的概念、产生背景和核心价值（省、快、稳、密四个驱动力）</li><li>理解边缘与云的互补协同关系（正反馈循环：边缘执行→云端训练→模型下发→边缘更准）</li><li>了解边缘计算的典型系统架构（设备层→网关层→边缘服务器→云端），理解IIRA功能视角与部署视角的区别</li><li>了解ISA-95/IIRA与边缘三层架构的映射关系，理解边缘计算在工业分层模型中的定位</li><li>了解软PLC的概念及其与传统硬PLC的区别，理解软PLC的适用边界（安全功能仍需硬件安全PLC）</li><li>理解&quot;数据预处理&quot;&quot;本地决策&quot;&quot;数据筛选上传&quot;三种边缘计算典型工作模式</li></ol><h3 id="技能目标" tabindex="-1">技能目标 <a class="header-anchor" href="#技能目标" aria-label="Permalink to &quot;技能目标&quot;">​</a></h3><ol><li>能用Node-RED搭建一个模拟边缘数据处理流（数据产生→本地过滤→选择性上传）</li><li>能在Node-RED中实现简单的数据阈值判断和异常检测逻辑</li><li>能通过实验数据对比&quot;全量上传&quot;和&quot;边缘筛选后上传&quot;的数据量差异</li><li>能在Ubuntu上安装并运行OpenPLC，通过ModbusTCP与Node-RED协同工作</li></ol><h3 id="素养目标" tabindex="-1">素养目标 <a class="header-anchor" href="#素养目标" aria-label="Permalink to &quot;素养目标&quot;">​</a></h3><ul><li><strong>分级思维</strong>：建立&quot;分级处理&quot;的架构思维——不是所有数据都值得传到云端</li><li><strong>精益求精</strong>：培养精益求精的工程态度——让每一个比特都有价值</li><li><strong>数据安全意识</strong>：理解敏感数据不出厂的重要性</li><li><strong>制造强国精神</strong>：了解我国在边缘计算领域的自主创新成果</li><li><strong>安全底线意识</strong>：理解功能安全与常规控制的边界，软PLC管&quot;干活&quot;，安全PLC管&quot;保命&quot;</li></ul><hr><h2 id="二、课时分配与教学安排" tabindex="-1">二、课时分配与教学安排 <a class="header-anchor" href="#二、课时分配与教学安排" aria-label="Permalink to &quot;二、课时分配与教学安排&quot;">​</a></h2><table tabindex="0"><thead><tr><th>课次</th><th>课时</th><th>内容</th><th>教学类型</th><th>重点/难点</th></tr></thead><tbody><tr><td>第1次课</td><td>2h</td><td>4.1 场景导入 + 4.2 边缘计算概念与核心价值</td><td>理论</td><td><strong>重点</strong>：四个核心驱动力、边缘与云的正反馈循环<br><strong>难点</strong>：正反馈循环的理解</td></tr><tr><td>第2次课</td><td>2h</td><td>4.3 边缘计算三层架构 + 4.4 软PLC概念</td><td>理论</td><td><strong>重点</strong>：三层架构、ISA-95/IIRA映射、软PLC与硬PLC的区别<br><strong>难点</strong>：功能视角与部署视角的区别、ISA-95/IIRA映射关系</td></tr><tr><td>第3次课</td><td>2h</td><td>4.5 实践：Node-RED边缘数据处理流</td><td>实践</td><td><strong>重点</strong>：Switch节点阈值判断、滑动均值计算<br><strong>难点</strong>：context对象的理解</td></tr><tr><td>第4次课</td><td>2h</td><td>4.6 实践：数据筛选对比 + 软PLC初体验</td><td>实践</td><td><strong>重点</strong>：数据量对比、OpenPLC与Node-RED协同<br><strong>难点</strong>：OpenPLC安装问题排查</td></tr></tbody></table><hr><h2 id="三、各节教学实施建议" tabindex="-1">三、各节教学实施建议 <a class="header-anchor" href="#三、各节教学实施建议" aria-label="Permalink to &quot;三、各节教学实施建议&quot;">​</a></h2><h3 id="_4-1-数据都往云端传-行得通吗-理论" tabindex="-1">4.1 数据都往云端传，行得通吗？（理论） <a class="header-anchor" href="#_4-1-数据都往云端传-行得通吗-理论" aria-label="Permalink to &quot;4.1 数据都往云端传，行得通吗？（理论）&quot;">​</a></h3><h4 id="教学导入-20分钟" tabindex="-1">教学导入（20分钟） <a class="header-anchor" href="#教学导入-20分钟" aria-label="Permalink to &quot;教学导入（20分钟）&quot;">​</a></h4><ol><li><strong>开场互动</strong>：让学生算一笔账——如果一个工厂有1万台传感器，每台每秒采50个点，一天产生多少数据？现场算，让学生直观感受到数据量的巨大。</li><li><strong>播放视频</strong>：IIoT-V4-01《边缘计算——数据洪流的解决方案》，让学生对边缘计算有初步印象。</li><li><strong>引出核心问题</strong>：全量上传到底行不行？为什么不行？怎么办？</li></ol><h4 id="知识讲解-60分钟" tabindex="-1">知识讲解（60分钟） <a class="header-anchor" href="#知识讲解-60分钟" aria-label="Permalink to &quot;知识讲解（60分钟）&quot;">​</a></h4><ol><li><strong>海上风电场场景</strong>：详细计算500GB/天数据量的来源，卫星通信的成本和延迟问题，强调&quot;全量上传不可行&quot;。</li><li><strong>SMT产线场景</strong>：1500MB/秒数据量，千兆光纤都不够，只有1%数据有价值——引出&quot;筛选&quot;的必要性。</li><li><strong>解决思路</strong>：把处理搬到数据产生的地方——边缘计算的核心思想。</li><li><strong>工业视角</strong>：从&quot;云就是一切&quot;到&quot;边缘+云协同&quot;的观念转变。</li></ol><h4 id="回顾与讨论-20分钟" tabindex="-1">回顾与讨论（20分钟） <a class="header-anchor" href="#回顾与讨论-20分钟" aria-label="Permalink to &quot;回顾与讨论（20分钟）&quot;">​</a></h4><ul><li>小组讨论：你还能想到哪些工业场景适合用边缘计算？</li><li>请2-3组分享。</li></ul><h4 id="常见问题与解答" tabindex="-1">常见问题与解答 <a class="header-anchor" href="#常见问题与解答" aria-label="Permalink to &quot;常见问题与解答&quot;">​</a></h4><ul><li>Q: 边缘计算就是在车间放一台电脑？</li><li>A: 不止这么简单。边缘计算是一套体系，包括边缘网关、边缘服务器、云端，以及它们之间的协同。4.3节会详细讲这个架构。</li></ul><hr><h3 id="_4-2-边缘计算-在数据源头做第一轮处理-理论" tabindex="-1">4.2 边缘计算：在数据源头做第一轮处理（理论） <a class="header-anchor" href="#_4-2-边缘计算-在数据源头做第一轮处理-理论" aria-label="Permalink to &quot;4.2 边缘计算：在数据源头做第一轮处理（理论）&quot;">​</a></h3><h4 id="教学导入-10分钟" tabindex="-1">教学导入（10分钟） <a class="header-anchor" href="#教学导入-10分钟" aria-label="Permalink to &quot;教学导入（10分钟）&quot;">​</a></h4><ul><li>承接4.1的结论——全量上传不可行，那怎么办？引出边缘计算的定义：在靠近数据源头的一端提供计算、存储和网络服务。核心理念只有一句话：<strong>数据在哪产生，就在哪先做处理。</strong></li><li>回到风电场例子，对比&quot;全量上传&quot;和&quot;边缘筛选&quot;两种方案的数据量差异。</li></ul><h4 id="四个核心驱动力-40分钟" tabindex="-1">四个核心驱动力（40分钟） <a class="header-anchor" href="#四个核心驱动力-40分钟" aria-label="Permalink to &quot;四个核心驱动力（40分钟）&quot;">​</a></h4><ol><li><strong>省——带宽成本</strong>：用风电场的例子说明，750,000点/秒骤降到约100个事件/分钟，卫星通信费用降了两个数量级。</li><li><strong>快——延迟要求</strong>：毫秒级响应不能等云端。轴承温度超85℃必须立即降功率——数据绕地球半圈到云端再回来，物理延迟已经超限。</li><li><strong>稳——离线可靠性</strong>：海上平台、矿山矿井、高原铁路——断网时边缘节点根据本地数据和预设逻辑独立决策，恢复后同步。</li><li><strong>密——数据隐私</strong>：合金热处理温度曲线、产线工时节拍、催化配比——敏感数据不出厂，只上传脱敏后的统计结果。</li></ol><h4 id="边缘不是要取代云——正反馈循环-30分钟" tabindex="-1">边缘不是要取代云——正反馈循环（30分钟） <a class="header-anchor" href="#边缘不是要取代云——正反馈循环-30分钟" aria-label="Permalink to &quot;边缘不是要取代云——正反馈循环（30分钟）&quot;">​</a></h4><ol><li><strong>破除误解</strong>：先问学生&quot;有了边缘计算还需要云计算吗？&quot;——引出&quot;边缘和云是互补关系&quot;的核心观点。</li><li><strong>对比分析</strong>： <ul><li>边缘擅长：&quot;快&quot;和&quot;省&quot;——实时反应、只传有价值的数据</li><li>云端擅长：&quot;深&quot;和&quot;广&quot;——海量历史数据训练AI模型、大规模仿真</li></ul></li><li><strong>正反馈循环讲解</strong>（重点+难点）： <ul><li>边缘网关实时判断轴承有没有异常（毫秒级决策）</li><li>云端分析过去半年的振动数据训练更准确的预测模型</li><li>新模型推送到边缘网关</li><li>边缘执行的准确率因此越来越高</li><li>&quot;边缘执行→云端训练→模型下发→边缘更准&quot;形成正反馈循环</li></ul></li><li><strong>教学建议</strong>：在黑板上画出正反馈循环示意图（或使用教材图4-x），用箭头标注四个环节，强调这是一个<strong>不断自我强化的循环</strong>，是工业互联网最理想的运转形态。</li></ol><h4 id="回顾与讨论-20分钟-1" tabindex="-1">回顾与讨论（20分钟） <a class="header-anchor" href="#回顾与讨论-20分钟-1" aria-label="Permalink to &quot;回顾与讨论（20分钟）&quot;">​</a></h4><ul><li>小组讨论：边缘和云各自擅长什么？为什么说它们是互补而不是替代？</li><li>请2-3组分享，教师总结正反馈循环的核心逻辑。</li></ul><h4 id="常见问题与解答-1" tabindex="-1">常见问题与解答 <a class="header-anchor" href="#常见问题与解答-1" aria-label="Permalink to &quot;常见问题与解答&quot;">​</a></h4><ul><li>Q: 边缘计算会取代云计算吗？</li><li>A: 不会。边缘和云是互补关系，不是替代关系。边缘擅长实时决策和数据筛选，云端擅长深度分析和模型训练。两者协同形成正反馈循环——边缘执行越准，上传的数据越有价值，云端训练的模型也越好，下发的模型又让边缘更准。这是一个不断自我强化的过程。</li><li>Q: 正反馈循环中的&quot;模型下发&quot;具体是什么？</li><li>A: 比如云端用半年历史数据训练出一个&quot;轴承失效预测模型&quot;，这个模型可以是一个AI推理程序，打包后推送到边缘网关上运行。边缘网关从&quot;简单阈值判断&quot;升级为&quot;AI预测判断&quot;，准确率大幅提升。</li></ul><hr><h3 id="_4-3-边缘计算的系统架构-理论" tabindex="-1">4.3 边缘计算的系统架构（理论） <a class="header-anchor" href="#_4-3-边缘计算的系统架构-理论" aria-label="Permalink to &quot;4.3 边缘计算的系统架构（理论）&quot;">​</a></h3><h4 id="教学导入-10分钟-1" tabindex="-1">教学导入（10分钟） <a class="header-anchor" href="#教学导入-10分钟-1" aria-label="Permalink to &quot;教学导入（10分钟）&quot;">​</a></h4><ul><li>用快递分级处理的类比开场——小区驿站、区域分拨中心、全国枢纽，对应边缘网关、边缘服务器、云端。</li><li>引出问题：边缘计算不是&quot;在车间摆一台电脑&quot;这么随意，按照部署位置和算力强弱，可以分为三个层级。</li></ul><h4 id="三层架构讲解-40分钟" tabindex="-1">三层架构讲解（40分钟） <a class="header-anchor" href="#三层架构讲解-40分钟" aria-label="Permalink to &quot;三层架构讲解（40分钟）&quot;">​</a></h4><ol><li><strong>边缘网关</strong>：最靠近设备的计算节点，实际部署最多的边缘形态。硬件是工业级工控机或智能路由器，装在电柜里。运行Linux和数据处理软件（Node-RED就是其中一种）。日常工作：协议转换、数据预处理、断网缓存。</li><li><strong>边缘服务器</strong>：比网关更强大的边缘算力。装配GPU的工业PC或服务器，部署在车间旁的独立机柜。AI推理延迟10-50ms（云端200ms以上），适合产线节拍快的场景。</li><li><strong>云端</strong>：扮演&quot;总部&quot;角色。长期存储全量历史数据、训练AI模型、模型下发、全局调度和经营决策。</li></ol><h4 id="isa-95-iira映射关系-20分钟" tabindex="-1">ISA-95/IIRA映射关系（20分钟） <a class="header-anchor" href="#isa-95-iira映射关系-20分钟" aria-label="Permalink to &quot;ISA-95/IIRA映射关系（20分钟）&quot;">​</a></h4><ol><li><strong>展示映射表</strong>：</li></ol><table tabindex="0"><thead><tr><th>边缘层级</th><th>ISA-95 层级</th><th>IIRA 层级</th></tr></thead><tbody><tr><td>现场设备（传感器、执行器）</td><td>L0-L1</td><td>边缘层</td></tr><tr><td>边缘网关</td><td>L1-L2 之间</td><td>边缘层</td></tr><tr><td>边缘服务器</td><td>L2 附近</td><td>边缘层与平台层之间</td></tr><tr><td>云端</td><td>L3-L4</td><td>平台层 + 应用层 + 业务层</td></tr></tbody></table><ol start="2"><li><strong>讲解要点</strong>： <ul><li>边缘计算填补的是L0-L1（设备）和L3-L4（云端）之间的技术空白</li><li>数据不必&quot;一步登天&quot;，而是经过逐级处理、过滤、浓缩</li></ul></li><li><strong>与第2章的衔接</strong>：IIRA四层模型中&quot;边缘层&quot;大致对应&quot;边缘网关+边缘服务器&quot;两层，IIRA的&quot;平台层&quot;对应&quot;云端&quot;。IIRA是<strong>功能视角</strong>的分层（数据在哪个环节被怎样处理），本节是<strong>部署视角</strong>的分层（设备装在哪里、算力有多强）——两者看的是同一套系统，只是切面不同。</li></ol><h4 id="课程思政融入-10分钟" tabindex="-1">课程思政融入（10分钟） <a class="header-anchor" href="#课程思政融入-10分钟" aria-label="Permalink to &quot;课程思政融入（10分钟）&quot;">​</a></h4><ul><li>介绍华为Atlas边缘计算平台、阿里云Link IoT Edge、腾讯EdgeOne等国产边缘计算平台——自主创新，打破国外厂商在工控领域的技术垄断。</li><li>引导学生树立自主创新意识，用技术支撑制造强国建设。</li></ul><h4 id="回顾与讨论-20分钟-2" tabindex="-1">回顾与讨论（20分钟） <a class="header-anchor" href="#回顾与讨论-20分钟-2" aria-label="Permalink to &quot;回顾与讨论（20分钟）&quot;">​</a></h4><ul><li>小组讨论：边缘网关、边缘服务器、云端三者各擅长什么？边缘服务器和边缘网关的关键区别是什么？</li><li>请2-3组分享。</li></ul><h4 id="常见问题与解答-2" tabindex="-1">常见问题与解答 <a class="header-anchor" href="#常见问题与解答-2" aria-label="Permalink to &quot;常见问题与解答&quot;">​</a></h4><ul><li>Q: ISA-95和IIRA有什么区别？</li><li>A: ISA-95是制造业的分层标准，从L0（物理过程）到L4（企业经营），侧重于企业功能和信息流的分层；IIRA是工业互联网参考架构，从边缘层到业务层，侧重于数据和功能的分层。两者看的是同一套系统，但视角不同——ISA-95更偏&quot;工厂内部怎么组织&quot;，IIRA更偏&quot;工业互联网怎么架构&quot;。映射表帮助我们把边缘计算的三层架构放到这两个标准框架中去理解。</li><li>Q: 为什么边缘网关在ISA-95中处于&quot;L1-L2之间&quot;而不是明确的某一层？</li><li>A: 因为边缘网关的功能横跨了L1（感知执行）和L2（监控监控）——它既从L1的设备采集数据，又做L2级别的监控判断。所以它不是严格属于某一层，而是&quot;跨层&quot;的。</li></ul><hr><h3 id="_4-4-走近软plc-当控制变成软件-理论" tabindex="-1">4.4 走近软PLC：当控制变成软件（理论） <a class="header-anchor" href="#_4-4-走近软plc-当控制变成软件-理论" aria-label="Permalink to &quot;4.4 走近软PLC：当控制变成软件（理论）&quot;">​</a></h3><h4 id="教学导入-10分钟-2" tabindex="-1">教学导入（10分钟） <a class="header-anchor" href="#教学导入-10分钟-2" aria-label="Permalink to &quot;教学导入（10分钟）&quot;">​</a></h4><ul><li>回顾第3章的PLC概念——方方正正的铁盒，装在电柜里，插满接线端子。</li><li>引出问题：PLC的控制逻辑能不能从专用硬件中&quot;跑出来&quot;，变成纯软件？</li></ul><h4 id="知识讲解-50分钟" tabindex="-1">知识讲解（50分钟） <a class="header-anchor" href="#知识讲解-50分钟" aria-label="Permalink to &quot;知识讲解（50分钟）&quot;">​</a></h4><ol><li><strong>传统硬PLC</strong>：专用硬件、独立处理器和内存、厂商定制实时操作系统。优点是稳——连续运行十年不重启。缺点是封闭——每家PLC只能用自家软件编程。</li><li><strong>软PLC</strong>：把PLC的控制逻辑从专用硬件中剥离出来，变成纯软件，运行在通用工业PC上。打破&quot;硬件绑定&quot;——同一台工控机上可以跑不同来源的控制程序。</li><li><strong>主流产品</strong>：倍福TwinCAT、Codesys、西门子SIMATIC软件控制器。</li><li><strong>软PLC为什么属于边缘计算</strong>：物理形态就是边缘侧的工控机，一个软件进程。同一台设备上，软PLC进程控制传送带启停，Node-RED进程采集振动数据分析设备健康状态——控制和分析不再分家。</li><li><strong>重要强调</strong>：软PLC≠安全PLC。安全功能（急停、安全门联锁、安全光幕等）有独立国际标准（IEC 61508 / ISO 13849），要求使用经过安全认证的硬件。<strong>软PLC管&quot;干活&quot;，安全PLC管&quot;保命&quot;，两者各司其职，不可互相替代。</strong></li></ol><h4 id="回顾与讨论-20分钟-3" tabindex="-1">回顾与讨论（20分钟） <a class="header-anchor" href="#回顾与讨论-20分钟-3" aria-label="Permalink to &quot;回顾与讨论（20分钟）&quot;">​</a></h4><ul><li>小组讨论：软PLC和硬PLC的根本区别是什么？什么场景下必须使用硬件安全PLC？</li><li>请2-3组分享。</li></ul><h4 id="常见问题与解答-3" tabindex="-1">常见问题与解答 <a class="header-anchor" href="#常见问题与解答-3" aria-label="Permalink to &quot;常见问题与解答&quot;">​</a></h4><ul><li>Q: 软PLC能完全替代硬PLC吗？</li><li>A: 不能。在安全级别最高的场景中（急停按钮回路、安全光幕联锁等），仍然需要经过安全认证的硬件安全PLC或安全继电器。软PLC解决的是&quot;控制逻辑软件化&quot;的问题，安全PLC解决的是&quot;任何软件故障情况下安全回路仍然有效&quot;的问题。</li><li>Q: 软PLC运行在通用操作系统上，会不会不稳定？</li><li>A: 这确实是软PLC面临的挑战之一。主流软PLC产品（如TwinCAT）会使用实时操作系统扩展或双系统方案来保证实时性。但在最苛刻的安全场景中，专用硬件的可靠性仍然是不可替代的。</li></ul><hr><h3 id="_4-5-动手实践-用-node-red-构建边缘数据处理流-实践" tabindex="-1">4.5 动手实践：用 Node-RED 构建边缘数据处理流（实践） <a class="header-anchor" href="#_4-5-动手实践-用-node-red-构建边缘数据处理流-实践" aria-label="Permalink to &quot;4.5 动手实践：用 Node-RED 构建边缘数据处理流（实践）&quot;">​</a></h3><h4 id="实践准备-10分钟" tabindex="-1">实践准备（10分钟） <a class="header-anchor" href="#实践准备-10分钟" aria-label="Permalink to &quot;实践准备（10分钟）&quot;">​</a></h4><ul><li>确认学生Node-RED环境是否可用（<a href="http://xn--IP-tx5di3ni80c:1880" target="_blank" rel="noreferrer">http://虚拟机IP:1880</a>）</li><li>回顾4.2节讲过的边缘计算三种工作模式：数据预处理、本地决策、数据筛选上传——本次实践将全部实现</li></ul><h4 id="任务一-用-function-节点模拟传感器-25分钟" tabindex="-1">任务一：用 Function 节点模拟传感器（25分钟） <a class="header-anchor" href="#任务一-用-function-节点模拟传感器-25分钟" aria-label="Permalink to &quot;任务一：用 Function 节点模拟传感器（25分钟）&quot;">​</a></h4><ol><li><strong>分步演示</strong>：如何用Inject+Function节点模拟传感器数据。</li><li><strong>关键讲解</strong>：随机数生成（Math.random()）、异常值注入（5%概率高温、3%概率振动尖峰）的代码逻辑。</li><li><strong>学生操作</strong>：搭建节点、部署、观察数据。</li><li><strong>提示</strong>：如果学生没写过JavaScript，强调不需要担心——这段代码的逻辑就是用随机数模拟设备读数，偶尔加入异常值。</li></ol><h4 id="任务二-本地实时判断——温度超标立即报警-25分钟" tabindex="-1">任务二：本地实时判断——温度超标立即报警（25分钟） <a class="header-anchor" href="#任务二-本地实时判断——温度超标立即报警-25分钟" aria-label="Permalink to &quot;任务二：本地实时判断——温度超标立即报警（25分钟）&quot;">​</a></h4><ol><li><strong>类比讲解</strong>：阈值判断就像温度计报警——超过80度就报警，不需要等云端。</li><li><strong>学生操作</strong>：Switch节点配置、报警触发观察。</li><li><strong>强调重点</strong>：这是边缘计算最核心的价值——本地决策，毫秒级响应。从传感器数据产生到报警触发，延迟在毫秒以内，完全在Node-RED本地内存中完成。</li></ol><h4 id="任务三-数据预处理——计算滑动均值-40分钟" tabindex="-1">任务三：数据预处理——计算滑动均值（40分钟） <a class="header-anchor" href="#任务三-数据预处理——计算滑动均值-40分钟" aria-label="Permalink to &quot;任务三：数据预处理——计算滑动均值（40分钟）&quot;">​</a></h4><ol><li><strong>难点突破</strong>：context对象是学生最容易困惑的地方——用&quot;储物柜&quot;类比：context是每个节点自己的储物柜，多次调用之间数据不会丢。如果用普通的var声明，每次节点被触发时变量都会重新初始化，缓存就丢失了。</li><li><strong>代码讲解</strong>：滑动窗口逻辑——保留最近10个点、每30点输出一次。重点解释<code>return null</code>的含义——这次不输出任何数据，等下一次。</li><li><strong>学生操作</strong>：搭建滑动均值节点、观察输出频率。</li><li><strong>连线提醒</strong>：传感器模拟Function节点的输出需要<strong>同时连接到</strong>温度判断Switch节点和滑动均值Function节点（拖两根线出去）。</li></ol><h4 id="回顾与讨论-20分钟-4" tabindex="-1">回顾与讨论（20分钟） <a class="header-anchor" href="#回顾与讨论-20分钟-4" aria-label="Permalink to &quot;回顾与讨论（20分钟）&quot;">​</a></h4><ul><li>让学生用自己的话解释：为什么要在边缘做筛选？如果全部数据都上传会怎样？</li><li>观察Debug面板：温度超标报警是实时触发的，均值摘要是大约每30秒才出现一条——这就是边缘筛选的效果。</li></ul><h4 id="常见问题与解答-4" tabindex="-1">常见问题与解答 <a class="header-anchor" href="#常见问题与解答-4" aria-label="Permalink to &quot;常见问题与解答&quot;">​</a></h4><ul><li>Q: context对象怎么用？</li><li>A: <code>context.dataBuffer = context.dataBuffer || [];</code> 这句话的意思是&quot;如果有储物柜就用现有的，没有就新建一个空的&quot;。</li><li>Q: return null是什么意思？</li><li>A: 意思是这次不输出任何数据，等下一次。Function节点收到消息后如果不return一个msg对象，下游节点就不会被触发。</li><li>Q: 为什么传感器模拟节点要拖两根线出去？</li><li>A: 因为温度判断和滑动均值是两个独立的处理路径，需要同时接收传感器数据。温度判断是实时响应（每条数据都判断），滑动均值是批量处理（30条才输出一次），两者互不干扰。</li></ul><hr><h3 id="_4-6-动手实践-数据筛选对比-软plc初体验-实践" tabindex="-1">4.6 动手实践：数据筛选对比 + 软PLC初体验（实践） <a class="header-anchor" href="#_4-6-动手实践-数据筛选对比-软plc初体验-实践" aria-label="Permalink to &quot;4.6 动手实践：数据筛选对比 + 软PLC初体验（实践）&quot;">​</a></h3><h4 id="实践准备-10分钟-1" tabindex="-1">实践准备（10分钟） <a class="header-anchor" href="#实践准备-10分钟-1" aria-label="Permalink to &quot;实践准备（10分钟）&quot;">​</a></h4><ul><li>确认4.5节的Node-RED Flow仍然正常运行</li><li>确认Ubuntu虚拟机可用，SSH连接正常</li><li>回顾4.4节讲过的软PLC概念——现在要亲手装一个真实的软PLC</li></ul><h4 id="任务一-添加振动异常判断-20分钟" tabindex="-1">任务一：添加振动异常判断（20分钟） <a class="header-anchor" href="#任务一-添加振动异常判断-20分钟" aria-label="Permalink to &quot;任务一：添加振动异常判断（20分钟）&quot;">​</a></h4><ol><li><strong>讲解要点</strong>：振动异常需要实时检测，所以应该直接从传感器模拟节点取数据，而不是等滑动均值每30秒输出一次。</li><li><strong>学生操作</strong>：添加第二个Switch节点（振动判断，&gt;3mm/s），连接Debug节点。</li><li><strong>连线提醒</strong>：这是从传感器模拟节点出去的<strong>第三根线</strong>——传感器模拟节点现在同时连接三个下游节点。</li></ol><h4 id="任务二-用计数器看-数据量减少了多少-25分钟" tabindex="-1">任务二：用计数器看&quot;数据量减少了多少&quot;（25分钟） <a class="header-anchor" href="#任务二-用计数器看-数据量减少了多少-25分钟" aria-label="Permalink to &quot;任务二：用计数器看&quot;数据量减少了多少&quot;（25分钟）&quot;">​</a></h4><ol><li><strong>讲解要点</strong>：Node-RED的Debug面板对每个Debug节点有消息计数功能。点击调试消息旁边的数字图标，可以看到该节点自部署以来收到过多少条消息。</li><li><strong>学生操作</strong>：让系统稳定运行2分钟后，记录各Debug节点的计数： <ul><li>本地报警——温度超标：约6-10条（5%异常概率，实时判断）</li><li>振动异常——上传原始数据：约3-7条（3%异常概率，实时判断）</li><li>云端接收——均值汇总：约4条（每30秒一条均值摘要）</li></ul></li><li><strong>数据对比</strong>：全量120条 vs 筛选后约14-21条——<strong>数据量减少了约85%</strong>。强调这不是理论数字，而是学生亲眼看到的实验结果。</li><li><strong>教学建议</strong>：让学生把计数结果写在黑板上，全班对比——不同学生的随机数不同，结果会有差异，但减少比例大致相同。这恰好说明边缘筛选的效果是稳定的。</li></ol><h4 id="任务三-安装并体验openplc-55分钟" tabindex="-1">任务三：安装并体验OpenPLC（55分钟） <a class="header-anchor" href="#任务三-安装并体验openplc-55分钟" aria-label="Permalink to &quot;任务三：安装并体验OpenPLC（55分钟）&quot;">​</a></h4><ol><li><strong>安装OpenPLC</strong>（30分钟）： <ul><li>提前准备好编译好的虚拟机镜像，避免学生因编译失败浪费时间</li><li>分步演示安装步骤，强调依赖包安装（autoconf、libtool）</li><li>准备好故障排除提示（教材中已列出三种常见问题）</li><li>重启虚拟机后启动OpenPLC，确认Web界面可访问</li></ul></li><li><strong>上传控制程序</strong>（10分钟）： <ul><li>登录OpenPLC Web界面（默认用户名/密码：openplc）</li><li>上传hello_world.st示例程序</li><li>启动PLC，确认程序运行</li><li>强调：虽然简单，但它和真实PLC&quot;跑程序&quot;没有本质区别——只是这台PLC是用软件实现的</li></ul></li><li><strong>Node-RED读取PLC变量</strong>（15分钟）： <ul><li>在Node-RED中新建Flow</li><li>配置Modbus Read节点（TCP、127.0.0.1、端口502、FC3、起始地址0、数量1、轮询1秒）</li><li>连接Debug节点，部署</li><li>观察计数器值持续增长——1、2、3、4……</li><li><strong>总结</strong>：这一刻完成了软PLC的核心体验——一个纯软件的PLC运行时正在执行控制程序，另一套边缘数据处理工具通过ModbusTCP读取它的内部变量。两种软件跑在同一台虚拟机上，协议是它们唯一需要遵守的共同约定。</li></ul></li></ol><h4 id="回顾与讨论-10分钟" tabindex="-1">回顾与讨论（10分钟） <a class="header-anchor" href="#回顾与讨论-10分钟" aria-label="Permalink to &quot;回顾与讨论（10分钟）&quot;">​</a></h4><ul><li>让学生用自己的话描述&quot;硬PLC&quot;和&quot;软PLC&quot;的根本区别</li><li>讨论：在真实工厂中，OpenPLC的位置可能是什么？Node-RED的位置是什么？</li></ul><h4 id="常见问题与解答-5" tabindex="-1">常见问题与解答 <a class="header-anchor" href="#常见问题与解答-5" aria-label="Permalink to &quot;常见问题与解答&quot;">​</a></h4><ul><li>Q: OpenPLC安装失败怎么办？</li><li>A: 检查依赖包是否完整安装，特别是autoconf和libtool。如果编译报错，回到步骤1确认：<code>sudo apt install autoconf libtool -y</code>。</li><li>Q: Web界面打不开？</li><li>A: 检查Ubuntu防火墙是否放行了8080端口：<code>sudo ufw allow 8080</code>。</li><li>Q: Modbus读不到数据？</li><li>A: 确认PLC已启动（Web界面显示&quot;PLC is running&quot;），确认地址和端口配置正确（127.0.0.1:502），确认功能码为FC3、起始地址为0。</li><li>Q: Node-RED中Modbus Read节点报错&quot;Connection refused&quot;？</li><li>A: OpenPLC的ModbusTCP服务器默认在PLC启动后才开始监听。确认PLC已经启动并运行，然后重新部署Node-RED的Flow。</li></ul><hr><h2 id="四、教学评价建议" tabindex="-1">四、教学评价建议 <a class="header-anchor" href="#四、教学评价建议" aria-label="Permalink to &quot;四、教学评价建议&quot;">​</a></h2><h3 id="过程性评价" tabindex="-1">过程性评价 <a class="header-anchor" href="#过程性评价" aria-label="Permalink to &quot;过程性评价&quot;">​</a></h3><table tabindex="0"><thead><tr><th>评价环节</th><th>评价方式</th><th>评价内容</th><th>权重</th></tr></thead><tbody><tr><td>课堂讨论</td><td>教师观察+小组互评</td><td>能否用自己的话解释边缘计算的核心价值、正反馈循环逻辑</td><td>15%</td></tr><tr><td>4.5实践</td><td>任务评价表（自评30%+互评30%+师评40%）</td><td>节点配置正确性、报警触发、均值输出、原理理解</td><td>25%</td></tr><tr><td>4.6实践</td><td>任务评价表（自评30%+互评30%+师评40%）</td><td>振动判断配置、数据量对比、OpenPLC安装与通信</td><td>25%</td></tr><tr><td>思考与练习</td><td>书面作业</td><td>计算题、分析题、概念理解</td><td>20%</td></tr><tr><td>课堂表现</td><td>教师记录</td><td>出勤、参与度、帮助同学</td><td>15%</td></tr></tbody></table><h3 id="终结性评价要点" tabindex="-1">终结性评价要点 <a class="header-anchor" href="#终结性评价要点" aria-label="Permalink to &quot;终结性评价要点&quot;">​</a></h3><ul><li>能否准确说出边缘计算的四个核心驱动力并各举一例</li><li>能否画出边缘-云端正反馈循环示意图并解释四个环节</li><li>能否将边缘三层架构与ISA-95/IIRA进行对应</li><li>能否区分软PLC与硬PLC、软PLC与安全PLC</li><li>能否用实验数据说明&quot;边缘筛选后数据量减少约85%&quot;</li></ul><h3 id="评价特别关注" tabindex="-1">评价特别关注 <a class="header-anchor" href="#评价特别关注" aria-label="Permalink to &quot;评价特别关注&quot;">​</a></h3><ul><li><strong>正反馈循环理解</strong>：学生是否真正理解&quot;边缘执行→云端训练→模型下发→边缘更准&quot;的循环逻辑，还是仅仅记住了口号？可以通过让学生用自己的话复述来检验。</li><li><strong>ISA-95/IIRA映射</strong>：学生是否能区分&quot;功能视角&quot;和&quot;部署视角&quot;的不同？可以通过让学生解释&quot;为什么边缘网关在ISA-95中处于L1-L2之间&quot;来检验。</li><li><strong>安全底线意识</strong>：学生是否牢固建立了&quot;软PLC≠安全PLC&quot;的认知？这是工程伦理和安全意识的底线。</li></ul><hr><h2 id="五、教学资源清单" tabindex="-1">五、教学资源清单 <a class="header-anchor" href="#五、教学资源清单" aria-label="Permalink to &quot;五、教学资源清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源类型</th><th>资源名称</th><th>时长/大小</th><th>对应节次</th></tr></thead><tbody><tr><td>微课视频</td><td>IIoT-V4-01 边缘计算——数据洪流的解决方案</td><td>8分钟</td><td>4.1</td></tr><tr><td>操作演示视频</td><td>IIoT-V4-02 用Node-RED搭建边缘数据处理流</td><td>12分钟</td><td>4.5</td></tr><tr><td>操作演示视频</td><td>IIoT-V4-03 OpenPLC安装与Node-RED集成</td><td>12分钟</td><td>4.6</td></tr><tr><td>工具软件</td><td>OpenPLC_v3 预编译镜像</td><td>~2GB</td><td>4.6</td></tr><tr><td>教学挂图</td><td>边缘-云端正反馈循环示意图</td><td>1张</td><td>4.2</td></tr><tr><td>教学挂图</td><td>边缘计算三层架构图</td><td>1张</td><td>4.3</td></tr><tr><td>教学挂图</td><td>ISA-95/IIRA与边缘三层架构映射表</td><td>1张</td><td>4.3</td></tr><tr><td>实践材料</td><td>4.5实践任务评价表（打印件）</td><td>1份/人</td><td>4.5</td></tr><tr><td>实践材料</td><td>4.6实践任务评价表（打印件）</td><td>1份/人</td><td>4.6</td></tr></tbody></table><hr><h2 id="六、思政融入设计说明" tabindex="-1">六、思政融入设计说明 <a class="header-anchor" href="#六、思政融入设计说明" aria-label="Permalink to &quot;六、思政融入设计说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>融入点</th><th>结合内容</th><th>教学方法</th><th>预期效果</th></tr></thead><tbody><tr><td>制造强国</td><td>我国边缘计算自主创新成果（华为Atlas、阿里云Link IoT Edge、腾讯EdgeOne）</td><td>案例展示+讨论</td><td>树立自主创新意识</td></tr><tr><td>数据安全</td><td>数据隐私不出厂（4.2&quot;密&quot;驱动力）</td><td>知识框+思考题</td><td>建立数据安全意识</td></tr><tr><td>工程师伦理</td><td>安全功能必须用硬件安全PLC（4.4软PLC≠安全PLC）</td><td>案例分析</td><td>培养严谨的工程态度和安全底线意识</td></tr><tr><td>精益求精</td><td>数据筛选，让每一个比特都有价值（4.5/4.6实践数据对比）</td><td>实践+数据对比</td><td>培养精益求精的态度</td></tr><tr><td>协同思维</td><td>边缘与云的正反馈循环（4.2）</td><td>图示+讨论</td><td>建立系统协同思维</td></tr></tbody></table><hr><h2 id="七、思考与练习参考答案" tabindex="-1">七、思考与练习参考答案 <a class="header-anchor" href="#七、思考与练习参考答案" aria-label="Permalink to &quot;七、思考与练习参考答案&quot;">​</a></h2><h3 id="选择题" tabindex="-1">选择题 <a class="header-anchor" href="#选择题" aria-label="Permalink to &quot;选择题&quot;">​</a></h3><ol><li><strong>C</strong>（边缘计算不是要替代云计算，而是互补）</li><li><strong>B</strong>（边缘网关部署在靠近设备的地方）</li><li><strong>B</strong>（软PLC的控制逻辑以纯软件形式运行在通用工控机上）</li><li><strong>C</strong>（JavaScript）</li><li><strong>B</strong>（消除传感器读数的瞬时随机噪声）</li><li><strong>C</strong>（ModbusTCP）</li><li><strong>B</strong>（边缘和云的互补协同关系）</li></ol><h3 id="判断题" tabindex="-1">判断题 <a class="header-anchor" href="#判断题" aria-label="Permalink to &quot;判断题&quot;">​</a></h3><ol><li><strong>×</strong>（有价值的数据还是要上传到云端，边缘和云是互补关系）</li><li><strong>√</strong></li><li><strong>√</strong></li><li><strong>√</strong></li><li><strong>×</strong>（OpenPLC是开源项目，不需要购买许可证）</li><li><strong>√</strong></li><li><strong>√</strong></li></ol><h3 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><ol><li><p><strong>计算过程</strong>：</p><ul><li>每秒数据量：50个点 × 8字节 = 400字节/秒</li><li>50个传感器：50 × 400 = 20,000字节/秒 = 20KB/秒</li><li>10Mbps带宽：10Mbps = 1.25MB/秒 = 1,250KB/秒</li><li>结论：20KB/秒 &lt; 1,250KB/秒，单条产线能全部实时上传</li><li><strong>延伸思考</strong>：如果是100条产线，就是2000KB/秒，超过10Mbps带宽，就需要边缘计算了</li></ul></li><li><p><strong>答案</strong>：</p><ul><li>协议转换 → 省（带宽成本，因为MQTT更轻量）</li><li>阈值判断 → 快（延迟要求，本地立即报警）</li><li>断网缓存 → 稳（离线可靠性）</li></ul></li><li><p><strong>答案</strong>：可以。方案是：</p><ul><li>在旧机床旁边加一台工控机</li><li>用工控机上的IO模块采集机床信号</li><li>工控机上运行软PLC做控制</li><li>同时运行Node-RED做数据采集和分析</li></ul></li><li><p><strong>答案</strong>：手机语音助手的唤醒词检测是在<strong>本地</strong>做的。原因：</p><ul><li>快——唤醒词检测不需要复杂分析，本地就能做</li><li>省——不需要把所有声音都传到云端，节省带宽和云端成本</li><li>隐私——不需要把用户的所有声音都传到云端，保护隐私</li></ul></li></ol><hr><h2 id="八、学生常见错误预判" tabindex="-1">八、学生常见错误预判 <a class="header-anchor" href="#八、学生常见错误预判" aria-label="Permalink to &quot;八、学生常见错误预判&quot;">​</a></h2><ol><li><p><strong>context对象理解困难</strong></p><ul><li>解决方案：用&quot;储物柜&quot;类比，context是每个节点自己的储物柜，多次调用之间数据不会丢。</li></ul></li><li><p><strong>滑动均值代码不会写</strong></p><ul><li>解决方案：提供代码模板，让学生填空。</li></ul></li><li><p><strong>OpenPLC安装失败</strong></p><ul><li>解决方案：提前准备好预编译的虚拟机镜像，让学生直接用。</li></ul></li><li><p><strong>Modbus读不到数据</strong></p><ul><li>解决方案：检查PLC是否启动，地址和端口是否正确。</li></ul></li><li><p><strong>正反馈循环理解停留在表面</strong></p><ul><li>解决方案：让学生用自己的话复述四个环节，并举一个具体例子（如轴承失效预测）来说明。避免学生只记住口号而不理解逻辑。</li></ul></li><li><p><strong>ISA-95/IIRA映射混淆</strong></p><ul><li>解决方案：强调两者是&quot;同一套系统，不同切面&quot;——ISA-95偏&quot;工厂内部怎么组织&quot;，IIRA偏&quot;工业互联网怎么架构&quot;。用映射表对照讲解，不要让学生死记硬背。</li></ul></li><li><p><strong>混淆&quot;软PLC≠安全PLC&quot;的含义</strong></p><ul><li>解决方案：用&quot;干活&quot;vs&quot;保命&quot;的类比，强调安全PLC的核心要求是&quot;任何软件故障情况下安全回路仍然有效&quot;——这是纯软件无法保证的。</li></ul></li></ol><hr><h2 id="九、教学反思要点" tabindex="-1">九、教学反思要点 <a class="header-anchor" href="#九、教学反思要点" aria-label="Permalink to &quot;九、教学反思要点&quot;">​</a></h2><p>课后请思考并记录：</p><ol><li>学生对哪个部分最感兴趣？哪个部分最困惑？</li><li>正反馈循环的讲解学生能理解吗？需要增加更多案例吗？</li><li>ISA-95/IIRA映射表的讲解是否清晰？学生能否区分功能视角和部署视角？</li><li>实践环节时间够吗？4.6节三个任务是否需要调整顺序或删减？</li><li>OpenPLC安装成功率高吗？需要提前准备镜像吗？</li><li>数据对比环节学生能直观感受到85%的减少吗？</li><li>&quot;软PLC≠安全PLC&quot;的安全底线意识是否深入人心？</li></ol><hr><p><strong>下一步</strong>：准备预编译OpenPLC镜像，准备4.5和4.6实践任务评价表打印件，准备正反馈循环和ISA-95/IIRA映射教学挂图。</p>',121)])])}const c=l(r,[["render",e]]);export{g as __pageData,c as default};
